// 负向对照：**同名数组但没导出**，而且**运行时也不真的 provide**。
//
// 它不是插件契约，不该被算作"提供了服务" —— 否则消费者那条真实缺失会被掩盖
// （假阴性方向，比假阳性更难发现）。
//
// 这条存在的理由很具体：修 `provideexported` 那个假阳性时，最省事的写法是
// "见 `provide` 就算"，那会把包内无关代码也收进来。这条就是挡住那种放松的钉子。
export { apply }

const provide = ['internalOnlyService']

function apply(ctx) {
  // 故意**不**调用 ctx.provide('internalOnlyService', ...)：
  // 数组不导出、又不在运行时注册，于是确实无人提供。
  ctx.logger.info('providerinternal ready')
}

const name = '@fixture/providerinternal'
